package com.srenterprises.entity;
import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="orders") public class CustomerOrder { @Id public UUID id=UUID.randomUUID(); @Column(name="order_number",nullable=false,unique=true) public String orderNumber; @ManyToOne @JoinColumn(name="customer_id") public User customer; @Enumerated(EnumType.STRING) public OrderStatus status=OrderStatus.PENDING; public BigDecimal subtotal; public BigDecimal shipping=BigDecimal.ZERO; public BigDecimal total; @Column(name="recipient_name") public String recipientName; public String email; public String phone; @Column(name="address_line") public String addressLine; public String city; public String state; @Column(name="postal_code") public String postalCode; @Column(name="created_at") public Instant createdAt=Instant.now(); @Column(name="updated_at") public Instant updatedAt=Instant.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL) public List<OrderItem> items=new ArrayList<>(); }
